    69  bool KGzipFilter::init(int mode)
    70  {
    71      switch (filterFlags()) {
    72      case NoHeaders:
    73          return init(mode, RawDeflate);
    74      case WithHeaders:
    75          return init(mode, GZipHeader);
    76      case ZlibHeaders:
    77          return init(mode, ZlibHeader);
    78      }
    79      return false;
    80  }
    81
    82  bool KGzipFilter::init(int mode, Flag flag)
    83  {
    84      if (d->isInitialized) {
    85          terminate();
    86      }
    87      d->zStream.next_in = Z_NULL;
    88      d->zStream.avail_in = 0;
    89      if (mode == QIODevice::ReadOnly) {
    90          const int windowBits = (flag == RawDeflate)
    91                                 ? -MAX_WBITS /*no zlib header*/
    92                                 : (flag == GZipHeader) ?
    93                                 MAX_WBITS + 32 /* auto-detect and eat gzip header */
    94                                 : MAX_WBITS /*zlib header*/;
    95          const int result = inflateInit2(&d->zStream, windowBits);
    96          if (result != Z_OK) {
    97              //qCDebug(KArchiveLog) << "inflateInit2 returned " << result;
    98              return false;
    99          }
   100      } else if (mode == QIODevice::WriteOnly) {
   101          int result = deflateInit2(&d->zStream, Z_DEFAULT_COMPRESSION, Z_DEFLATED, -MAX_WBITS, 8, Z_DEFAULT_STRATEGY); // same here
   102          if (result != Z_OK) {
   103              //qCDebug(KArchiveLog) << "deflateInit returned " << result;
   104              return false;
   105          }
   106      } else {
   107          //qCWarning(KArchiveLog) << "KGzipFilter: Unsupported mode " << mode << ". Only QIODevice::ReadOnly and QIODevice::WriteOnly supported";
   108          return false;
   109      }
   110      d->mode = mode;
   111      d->compressed = true;
   112      d->headerWritten = false;
   113      d->footerWritten = false;
   114      d->isInitialized = true;
   115      return true;
   116  }
