   350  KGzipFilter::Result KGzipFilter::compress(bool finish)
   351  {
   352      Q_ASSERT(d->compressed);
   353      Q_ASSERT(d->mode == QIODevice::WriteOnly);
   354
   355      const Bytef *p = d->zStream.next_in;
   356      ulong len = d->zStream.avail_in;
   357  #ifdef DEBUG_GZIP
   358      qCDebug(KArchiveLog) << "  calling deflate with avail_in=" << inBufferAvailable() << " avail_out=" << outBufferAvailable();
   359  #endif
   360      const int result = deflate(&d->zStream, finish ? Z_FINISH : Z_NO_FLUSH);
   361      if (result != Z_OK && result != Z_STREAM_END) {
   362          //qCDebug(KArchiveLog) << "  deflate returned " << result;
   363      }
   364      if (d->headerWritten) {
   365          //qCDebug(KArchiveLog) << "Computing CRC for the next " << len - d->zStream.avail_in << " bytes";
   366          d->crc = crc32(d->crc, p, len - d->zStream.avail_in);
   367      }
   368      KGzipFilter::Result callerResult = result == Z_OK ? KFilterBase::Ok : (Z_STREAM_END ? KFilterBase::End : KFilterBase::Error);
   369
   370      if (result == Z_STREAM_END && d->headerWritten && !d->footerWritten) {
   371          if (d->zStream.avail_out >= 8 /*footer size*/) {
   372              //qCDebug(KArchiveLog) << "finished, write footer";
   373              writeFooter();
   374          } else {
   375              // No room to write the footer (#157706/#188415), we'll have to do it on the next pass.
   376              //qCDebug(KArchiveLog) << "finished, but no room for footer yet";
   377              callerResult = KFilterBase::Ok;
   378          }
   379      }
   380      return callerResult;
   381  }

