   261  qint64 KCompressionDevice::readData(char *data, qint64 maxlen)
   262  {
   263      Q_ASSERT(d->filter->mode() == QIODevice::ReadOnly);
   264      //qCDebug(KArchiveLog) << "maxlen=" << maxlen;
   265      KFilterBase *filter = d->filter;
   266
   267      uint dataReceived = 0;
   268
   269      // We came to the end of the stream
   270      if (d->result == KFilterBase::End) {
   271          return dataReceived;
   272      }
   273
   274      // If we had an error, return -1.
   275      if (d->result != KFilterBase::Ok) {
   276          return -1;
   277      }
   278
   279      qint64 availOut = maxlen;
   280      filter->setOutBuffer(data, maxlen);
   281
   282      while (dataReceived < maxlen) {
   283          if (filter->inBufferEmpty()) {
   284              // Not sure about the best size to set there.
   285              // For sure, it should be bigger than the header size (see comment in readHeader)
   286              d->buffer.resize(BUFFER_SIZE);
   287              // Request data from underlying device
   288              int size = filter->device()->read(d->buffer.data(),
   289                                                d->buffer.size());
   290              //qCDebug(KArchiveLog) << "got" << size << "bytes from device";
   291              if (size) {
   292                  filter->setInBuffer(d->buffer.data(), size);
   293              } else {
   294                  // Not enough data available in underlying device for now
   295                  break;
   296              }
   297          }
   298          if (d->bNeedHeader) {
   299              (void) filter->readHeader();
   300              d->bNeedHeader = false;
   301          }
   302
   303          d->result = filter->uncompress();
   304
   305          if (d->result == KFilterBase::Error) {
   306              //qCWarning(KArchiveLog) << "KCompressionDevice: Error when uncompressing data";
   307              break;
   308          }
   309
   310          // We got that much data since the last time we went here
   311          uint outReceived = availOut - filter->outBufferAvailable();
   312          //qCDebug(KArchiveLog) << "avail_out = " << filter->outBufferAvailable() << " result=" << d->result << " outReceived=" << outReceived;
   313          if (availOut < uint(filter->outBufferAvailable())) {
   314              //qCWarning(KArchiveLog) << " last availOut " << availOut << " smaller than new avail_out=" << filter->outBufferAvailable() << " !";
   315          }
   316
   317          dataReceived += outReceived;
   318          data += outReceived;
   319          availOut = maxlen - dataReceived;
   320          if (d->result == KFilterBase::End) {
   321              // We're actually at the end, no more data to check
   322              if (filter->device()->atEnd()) {
   323                  break;
   324              }
   325
   326              // Still not done, re-init and try again
   327              filter->init(filter->mode());
   328          }
   329          filter->setOutBuffer(data, availOut);
   330      }

